package Akari.Add.RSA.crypto

import android.util.Base64

/**
 * Built-in standard AOSP RSA Software Attestation Key block,
 * ENCRYPTED with AES-256-GCM. Decrypted only in volatile memory on demand.
 */
object DefaultAospKey {
    private const val KEY_B64 = "V6DPt49BvqnjBp9/+XHaAJnW9eNbYeEB57f4FnjFJK0="
    private const val IV_B64 = "ggwpB/2pQtVcwMW/"
    private const val CIPHERTEXT_B64 =
        ""

    @Volatile
    private var cachedDecrypted: String? = null

    fun getRsaXml(): String {
        cachedDecrypted?.let { return it }
        val keyBytes = Base64.decode(KEY_B64, Base64.DEFAULT)
        val ivBytes = Base64.decode(IV_B64, Base64.DEFAULT)
        val cipherBytes = Base64.decode(CIPHERTEXT_B64, Base64.DEFAULT)
        val decryptedBytes = AesCipherHelper.decryptWithKey(cipherBytes, keyBytes, ivBytes)
        val result = String(decryptedBytes, Charsets.UTF_8)
        cachedDecrypted = result
        return result
    }

    fun clearCache() {
        cachedDecrypted = null
    }
}
